-1 \le \sin x \le 1 \text{ ดังนั้น} 
-1/x \le (\sin x)/x \le 1/x \text{ สำหรับ } x > 0 
\lim_{x \to \infty} \frac{\sin x}{x} = 0

The math steps are as follows:
\[
\lim_{x \to \frac{\pi}{3}} \frac{\tan^2 x - (1 + \sqrt{3}) \tan x + \sqrt{3}}{\sin x - \sqrt{3} \cos x}
\]
\[
= \lim_{x \to \frac{\pi}{3}} \frac{\tan^2 x - \tan x - \sqrt{3} \tan x + \sqrt{3}}{\sin x - \sqrt{3} \cos x}
\]
\[
= \lim_{x \to \frac{\pi}{3}} \frac{(\tan^2 x - \tan x) - (\sqrt{3} \tan x - \sqrt{3})}{\cos x \left( \frac{\sin x}{\cos x} - \sqrt{3} \right)}
\]
\[
= \lim_{x \to \frac{\pi}{3}} \frac{\tan x(\tan x - 1) - \sqrt{3}(\tan x - 1)}{\cos x \left( \frac{\sin x}{\cos x} - \sqrt{3} \right)}
\]
\[
= \lim_{x \to \frac{\pi}{3}} \frac{(\tan x - 1)(\tan x - \sqrt{3})}{\cos x(\tan x - \sqrt{3})}
\]
\[
= \lim_{x \to \frac{\pi}{3}} \frac{\tan x - 1}{\cos x}
\]
\[
= \frac{\sqrt{3} - 1}{\frac{\sqrt{3}}{2}}
\]
\[
= \frac{2(3 - \sqrt{3})}{3}
\]

The math steps are as follows:
\[
\lim_{x \to \frac{\pi}{6}} \frac{\cos x - \sin 2x}{4 \cos^2 x - 3}
\]
\[
= \lim_{x \to \frac{\pi}{6}} \frac{\cos x - 2 \sin x \cos x}{4(1 - \sin^2 x) - 3}
\]
\[
= \lim_{x \to \frac{\pi}{6}} \frac{\cos x(1 - 2 \sin x)}{1 - 4 \sin^2 x}
\]
\[
= \lim_{x \to \frac{\pi}{6}} \frac{\cos x(1 - 2 \sin x)}{(1 - 2 \sin x)(1 + 2 \sin x)}
\]
\[
= \lim_{x \to \frac{\pi}{6}} \frac{\cos x}{1 + 2 \sin x}
\]
\[
= \frac{\frac{\sqrt{3}}{2}}{1 + 1}
\]
\[
= \frac{\sqrt{3}}{4}
\]

The math steps are as follows:
\[
\lim_{x \to \frac{\pi}{4}} \frac{\tan^4 x + \cot^4 x - 2}{1 - \sin 2x}
= \lim_{x \to \frac{\pi}{4}} \frac{(\cot^2 x - \tan^2 x)^2}{(\cos x - \sin x)^2}
= \lim_{x \to \frac{\pi}{4}} \frac{(1 - \tan^4 x)^2}{\tan^4 x \cos^2 x (1 - \tan x)^2}
= \lim_{x \to \frac{\pi}{4}} \frac{(1 - \tan x)^2 (1 + \tan x)^2 (1 + \tan^2 x)^2}{\tan^4 x \cos^2 x (1 - \tan x)^2}
= \lim_{x \to \frac{\pi}{4}} \frac{(1 + \tan x)^2 (1 + \tan^2 x)^2}{\tan^4 x \cos^2 x}
= \frac{4 \times 4}{\frac{1}{2}} = 32
\]
